#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdatomic.h>
#include <pthread.h>

#define MAX_LEVEL 8
#define NUM_ITEMS 100000
#define NUM_THREADS 16

typedef struct skiplist_node {
    int key;
    int top_level;
    _Atomic(struct skiplist_node *) next[MAX_LEVEL];
} skiplist_node;

typedef struct {
    skiplist_node *head;
} skiplist_t;

bool skiplist_insert(skiplist_t *sl, int key, int top_level) {
    skiplist_node *new_node = malloc(sizeof(skiplist_node));
    if (!new_node) return false;
    new_node->key = key;
    new_node->top_level = top_level;
    for(int i = 0; i <= top_level; i++) {
        atomic_init(&new_node->next[i], NULL);
    }

    skiplist_node *preds[MAX_LEVEL];
    skiplist_node *succs[MAX_LEVEL];

retry:
    ;
    skiplist_node *pred = sl->head;
    for (int level = MAX_LEVEL - 1; level >= 0; level--) {
        skiplist_node *curr = atomic_load(&pred->next[level]);
        while (curr != NULL && curr->key < key) {
            pred = curr;
            curr = atomic_load(&pred->next[level]);
        }
        if (curr != NULL && curr->key == key) {
            free(new_node);
            return false;
        }
        preds[level] = pred;
        succs[level] = curr;
    }

    skiplist_node *expected = succs[0];
    while (true) {
        atomic_store(&new_node->next[0], expected);
        if (atomic_compare_exchange_weak(&preds[0]->next[0], &expected, new_node)) {
            break;
        }
        if (expected == succs[0]) {
            continue;
        }
        goto retry;
    }

    for (int level = 1; level <= top_level; level++) {
        expected = succs[level];
        while (true) {
            atomic_store(&new_node->next[level], expected);
            if (atomic_compare_exchange_weak(&preds[level]->next[level], &expected, new_node)) {
                break;
            }
            if (expected == succs[level]) {
                continue;
            }
            skiplist_node *p = sl->head;
            skiplist_node *c;
            for (int l = MAX_LEVEL - 1; l >= level; l--) {
                c = atomic_load(&p->next[l]);
                while (c != NULL && c->key < key) {
                    p = c;
                    c = atomic_load(&p->next[l]);
                }
            }
            preds[level] = p;
            succs[level] = c;
            expected = c;
        }
    }
    return true;
}

bool skiplist_search(skiplist_t *sl, int key) {
    skiplist_node *pred = sl->head;
    for (int level = MAX_LEVEL - 1; level >= 0; level--) {
        skiplist_node *curr = atomic_load(&pred->next[level]);
        while (curr != NULL && curr->key < key) {
            pred = curr;
            curr = atomic_load(&pred->next[level]);
        }
        if (curr != NULL && curr->key == key) {
            return true;
        }
    }
    return false;
}

int random_level(void) {
    int level = 0;
    while (rand() % 2 == 0 && level < MAX_LEVEL - 1) {
        level++;
    }
    return level;
}

skiplist_t *sl;

void* thread_func(void* arg) {
    int id = *(int*)arg;
    int items = NUM_ITEMS / NUM_THREADS;
    int start = id * items;
    for (int i = start; i < start + items; i++) {
        skiplist_insert(sl, i, random_level());
    }
    for (int i = start; i < start + items; i++) {
        if (!skiplist_search(sl, i)) {
            printf("Error: Key %d not found!\n", i);
            exit(1);
        }
    }
    return NULL;
}

int main(void) {
    sl = malloc(sizeof(skiplist_t));
    sl->head = malloc(sizeof(skiplist_node));
    sl->head->key = -1;
    sl->head->top_level = MAX_LEVEL - 1;
    for(int i=0; i<MAX_LEVEL; i++) {
        atomic_init(&sl->head->next[i], NULL);
    }

    pthread_t threads[NUM_THREADS];
    int thread_ids[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, thread_func, &thread_ids[i]);
    }
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    int count = 0;
    skiplist_node *curr = atomic_load(&sl->head->next[0]);
    while (curr) {
        count++;
        curr = atomic_load(&curr->next[0]);
    }

    if (count == NUM_ITEMS) {
        printf("FLAG: Skip List Success!\n");
    } else {
        printf("Error: Expected %d items, found %d\n", NUM_ITEMS, count);
    }
    return 0;
}
